ucs.falcon_logscale_query:
#event_simpleName=ProcessRollup2 NOT UserName=/(\$$|^SYSTEM$|^LOCAL SERVICE$|^NETWORK SERVICE$)/i
| case {
    ImageFileName=/\\(pchunter(32|64)?|powertool(64)?)\.exe$/i | stage := "KillAV" ;
    ImageFileName=/\\veeamp\.exe$/i | stage := "VeeamCredDump" ;
    CommandLine=/(Veeamp\.exe|VeeamCredentials|Veeam\.Backup\.Common\.dll)/i | stage := "VeeamCredDump" ;
    CommandLine=/(vssadmin(\.exe)?\s+delete\s+shadows|Win32_ShadowCopy|wmic\s+shadowcopy\s+delete)/i | stage := "InhibitRecovery" ;
    CommandLine=/(wevtutil(\.exe)?\s+cl\s|Clear-EventLog)/i | stage := "LogClear" ;
    CommandLine=/(net\s+stop\s+\"?Veeam|Stop-Service\s+-Name\s+\"?Veeam)/i | stage := "ServiceStopVeeam" ;
    * | stage := ""
}
| stage!=""
| groupBy([aid, ComputerName, UserName], function=[count(as=hits), count(field=stage, distinct=true, as=distinct_stages), min(@timestamp, as=first_seen), max(@timestamp, as=last_seen), collect([stage, ImageFileName, CommandLine])])
| window_min := (last_seen - first_seen) / 60000
| test(distinct_stages >= 2)
| test(window_min <= 60)
| sort(field=last_seen, order=desc)
